input.new_string:
/**
 * Roll a registration date forward to the next business day: a Saturday or Sunday, or a date
 * on the fixed public-holiday list, moves forward one day at a time until it lands on a
 * non-weekend, non-holiday day; a plain weekday is returned unchanged.
 */
private static java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
    while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
            || HOLIDAYS.contains(date)) {
        date = date.plusDays(1);
    }
    return date;
}

